--
-- Name: trg_embeddings_cache_check_dims(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_embeddings_cache_check_dims() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected INT;
    actual   INT;
BEGIN
    SELECT dims INTO expected
    FROM embedding_models
    WHERE id = new.model_id;

    IF expected IS NULL THEN
        RAISE EXCEPTION 'Unknown model_id %', new.model_id;
    END IF;

    IF octet_length(new.embedding) <> expected * 4 THEN
        raise exception 'Embedding dims mismatch: expected % bytes, got %',
        expected * 4, octet_length(new.embedding);
    END IF;

    RETURN new;
END;
$$;


