--

CREATE VIEW public.flow_system_events AS
 SELECT flow_configuration_events.event_id,
    flow_configuration_events.tx_id,
    'configurations'::text AS source_stream,
    flow_configuration_events.event_type,
    flow_configuration_events.event_time,
    flow_configuration_events.event_payload
   FROM public.flow_configuration_events
UNION ALL
 SELECT flow_trigger_events.event_id,
    flow_trigger_events.tx_id,
    'triggers'::text AS source_stream,
    flow_trigger_events.event_type,
    flow_trigger_events.event_time,
    flow_trigger_events.event_payload
   FROM public.flow_trigger_events
UNION ALL
 SELECT flow_events.event_id,
    flow_events.tx_id,
    'flows'::text AS source_stream,
    flow_events.event_type,
    flow_events.event_time,
    flow_events.event_payload
   FROM public.flow_events;


