    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: webhook_subscription_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_subscription_events (
    event_id bigint DEFAULT nextval('public.webhook_subscription_event_seq'::regclass) NOT NULL,
    subscription_id uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    event_type character varying(50) NOT NULL,
    event_payload jsonb NOT NULL
);


